def find_peak(arr, n):
    """Return the index of a peak element in ``arr``.

    A peak element is one that is greater than or equal to its
    neighbours (elements at the start/end of the array only need
    to be greater than or equal to their single neighbour, and a
    single-element array has its only element as the peak).

    Only the first ``n`` elements of ``arr`` are considered.
    If there are multiple peaks, the index of the first one is
    returned. Returns ``-1`` when there are no elements to check.
    """
    if arr is None or n is None:
        return -1
    limit = min(n, len(arr))
    if limit <= 0:
        return -1
    for i in range(limit):
        left_ok = i == 0 or arr[i] >= arr[i - 1]
        right_ok = i == limit - 1 or arr[i] >= arr[i + 1]
        if left_ok and right_ok:
            return i
    # Unreachable in practice (the maximum element is always a
    # peak), but kept as a safe fallback.
    return limit - 1
